import SwiftUI
@testable import ViewIsComming

/// One entry per shader-backed transition: the modifier the transition applies,
/// built with the same defaults as the public `Transition` factory.
///
/// `progress` follows the transition convention: 0 is the hidden (`active`) state and
/// 1 the resting (`identity`) state. Transitions that are asymmetric for insertion and
/// removal are listed in their insertion variant.
///
/// A transition that is added without an entry here fails
/// `TransitionContractTests.everyTransitionHasACase`.
@MainActor
let transitionCases: [(name: String, apply: (AnyView, Double) -> AnyView)] = [
    ("Angular", { view, p in AnyView(view.modifier(AngularModifier(progress: p, startingAngle: .degrees(90), clockwise: true))) }),
    ("BookFlip", { view, p in AnyView(view.modifier(BookFlipModifier(progress: p, direction: .right))) }),
    ("Bounce", { view, p in AnyView(view.modifier(BounceModifier(progress: p, bounces: 4.0, direction: .in))) }),
